BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL search_path=pg_catalog; SET LOCAL statement_timeout='20s'; SELECT jsonb_build_object('observedAt',clock_timestamp(),'readOnly',current_setting('transaction_read_only'),'schemaPrivileges',(SELECT jsonb_agg(jsonb_build_object('role',rolname,'createPublic',has_schema_privilege(rolname,'public','CREATE'),'usagePublic',has_schema_privilege(rolname,'public','USAGE'),'bypassRLS',rolbypassrls,'superuser',rolsuper) ORDER BY rolname) FROM pg_roles WHERE rolname IN('anon','authenticated','service_role','postgres')),'scopedLocks',(SELECT jsonb_agg(jsonb_build_object('relation',relation::regclass::text,'mode',mode,'granted',granted) ORDER BY relation,mode) FROM pg_locks WHERE relation IN('public.profiles'::regclass,'public.calculation_history'::regclass,'public.calculation_projects'::regclass,'public.saved_scenarios'::regclass) AND pid IS DISTINCT FROM pg_backend_pid()),'preparedTransactions',(SELECT count(*) FROM pg_prepared_xacts WHERE database=current_database()),'activity',(SELECT jsonb_agg(to_jsonb(s)) FROM(SELECT backend_type,usename,application_name,state,count(*) AS sessions FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() GROUP BY backend_type,usename,application_name,state)s),'authUserTriggers',(SELECT jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),'function',t.tgfoid::regprocedure::text,'functionSHA256',encode(sha256(convert_to(pg_get_functiondef(t.tgfoid),'UTF8')),'hex')) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid='auth.users'::regclass AND NOT t.tgisinternal)) AS evidence; COMMIT;
